package com.hssa.common.annotation; import com.hssa.common.validator.ValidUUIDValidator; import jakarta.validation.Constraint; import jakarta.validation.Payload; import java.lang.annotation.*; @Target({ElementType.FIELD, ElementType.PARAMETER}) @Retention(RetentionPolicy.RUNTIME) @Constraint(validatedBy = ValidUUIDValidator.class) public @interface ValidUUID { String message() default "Invalid UUID format"; Class<?>[] groups() default {}; Class<? extends Payload>[] payload() default {}; }
